    ensures(|ret: Vec<char>| ret[2] == lines[2][2]);
    ensures(|ret: Vec<char>| ret[3] == '\n');

    // Construct the result vector
    let mut result: Vec<char> = Vec::new();
    result.push(lines[0][0]);
